#!/bin/sh
# SPDX-License-Identifier: MPL-2.0
# Generated by DevContainer Builder. Override DCB_ENGINE, DOCKER_HOST/CONTAINER_HOST as needed.
set -eu

# Dev Containers feature Dockerfiles are generated outside Compose build contexts.
export COMPOSE_BAKE=false
export BUILDX_BAKE_ENTITLEMENTS_FS=0
ROOT=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)
CONFIG='.devcontainer/devcontainer.json'
ENGINE=${DCB_ENGINE:-docker}
command -v "$ENGINE" >/dev/null 2>&1 || { echo "Install $ENGINE and start its service or VM." >&2; exit 1; }
command -v node >/dev/null 2>&1 || { echo 'Install Node.js and the Dev Containers CLI: npm install -g @devcontainers/cli' >&2; exit 1; }
PROJECT=$(node -e 'process.stdout.write(require("node:crypto").createHash("sha256").update(process.argv[1]+"\0"+process.argv[2]).digest("hex").slice(0,24))' "$ROOT" "$CONFIG")
command -v devcontainer >/dev/null 2>&1 || { echo 'Install the CLI: npm install -g @devcontainers/cli' >&2; exit 1; }
ENGINE_PATH="$ENGINE"
if [ "$ENGINE" = podman ]; then ENGINE_PATH="$ROOT/.devcontainer/builder-podman.sh"; export DCB_PODMAN_EVENTS_SINCE=$(node -p 'new Date().toISOString()'); fi
if [ "$#" -eq 0 ]; then set -- /bin/sh; fi
exec devcontainer exec --workspace-folder "$ROOT" --config "$ROOT/$CONFIG" --docker-path "$ENGINE_PATH" --id-label "devcontainer-builder.project=$PROJECT" "$@"
